-- Query: find open orders for a customer, newest first.
SELECT Id, Total, CreatedAt
FROM Orders
WHERE CustomerId = 42 AND Status = 'Open'
ORDER BY CreatedAt DESC;

-- ✅ Composite index matching the WHERE columns and sort:
CREATE INDEX IX_Orders_Customer_Status_Created
    ON Orders (CustomerId, Status, CreatedAt DESC);

-- ❌ Index on (Status) alone: millions of 'Open' rows, still scans;
-- ❌ Index on (CreatedAt) alone: wrong filter order, useless for this query;
-- ❌ Function index trap: WHERE YEAR(CreatedAt) = 2026 can't use (CreatedAt) directly.
